{
  "name": "mPonics MRP - Smart Hydroponics Planner",
  "description": "A comprehensive Manufacturing Resource Planning system for modern hydroponic farms, featuring AI-powered crop scheduling, inventory management, and plant health diagnostics.",
  "requestFramePermissions": [
    "camera"
  ]
}

export interface Crop {
  id: string;
  name: string;
  variety: string;
  plantedDate: string;
  expectedHarvestDate: string;
  status: 'Seedling' | 'Vegetative' | 'Flowering' | 'Ready' | 'Harvested';
  health: number; // 0 to 100
  yield_estimate: number; // kg
}

export interface InventoryItem {
  id: string;
  name: string;
  category: 'Nutrient' | 'Seed' | 'Substrate' | 'Equipment';
  quantity: number;
  unit: string;
  threshold: number;
}

export interface MaintenanceTask {
  id: string;
  title: string;
  description: string;
  dueDate: string;
  priority: 'Low' | 'Medium' | 'High';
  isCompleted: boolean;
}

export interface AnalysisResult {
  status: string;
  diagnosis: string;
  recommendations: string[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { InventoryItem, Crop, AnalysisResult } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const getSmartPlanning = async (inventory: InventoryItem[], activeCrops: Crop[]) => {
  const ai = getAI();
  const prompt = `Based on the following inventory and current active crops, suggest an optimized planting schedule for the next 30 days to maximize yield and resource efficiency.

  Inventory: ${JSON.stringify(inventory)}
  Active Crops: ${JSON.stringify(activeCrops)}

  Provide a list of suggested planting actions.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            cropName: { type: Type.STRING },
            suggestedDate: { type: Type.STRING },
            reasoning: { type: Type.STRING },
            requiredResources: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["cropName", "suggestedDate", "reasoning"]
        }
      }
    }
  });

  return JSON.parse(response.text || "[]");
};

export const diagnosePlantImage = async (base64Image: string): Promise<AnalysisResult> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Image.split(',')[1], mimeType: 'image/jpeg' } },
        { text: "Analyze this plant image for signs of nutrient deficiency, pests, or disease. Provide a diagnosis and recommendations." }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          status: { type: Type.STRING, description: "Overall health status (Healthy, Warning, Critical)" },
          diagnosis: { type: Type.STRING, description: "Detailed identification of the issue" },
          recommendations: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Steps to fix the issue" }
        },
        required: ["status", "diagnosis", "recommendations"]
      }
    }
  });

  return JSON.parse(response.text || "{}");
};

import React, { useState, useRef } from 'react';
import { Sparkles, Camera, Upload, CheckCircle2, AlertCircle, Loader2 } from 'lucide-react';
import { diagnosePlantImage } from '../services/geminiService';
import { AnalysisResult } from '../types';

const SmartAdvisor: React.FC = () => {
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64String = reader.result as string;
        setPreview(base64String);
        setAnalyzing(true);
        try {
          const res = await diagnosePlantImage(base64String);
          setResult(res);
        } catch (error) {
          console.error("AI Analysis failed", error);
        } finally {
          setAnalyzing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-8 text-white relative overflow-hidden">
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-8">
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-4">
              <Sparkles size={24} className="text-indigo-200" />
              <span className="uppercase tracking-widest text-xs font-bold text-indigo-200">mPonics AI Advisor</span>
            </div>
            <h2 className="text-3xl font-bold mb-4">Optimize your growth cycles with intelligence</h2>
            <p className="text-indigo-100 text-lg mb-6">
              Upload a photo of your plants to diagnose nutrient deficiencies, identify pests, or get harvesting advice.
            </p>
            <div className="flex flex-wrap gap-4">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="bg-white text-indigo-600 px-6 py-3 rounded-xl font-bold hover:bg-indigo-50 transition-colors flex items-center gap-2"
              >
                <Camera size={20} />
                Snap Photo
              </button>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                className="hidden" 
                accept="image/*"
              />
            </div>
          </div>
          <div className="w-full md:w-64 aspect-square bg-indigo-500/30 rounded-2xl border-2 border-dashed border-indigo-400/50 flex flex-col items-center justify-center relative">
            {preview ? (
              <img src={preview} alt="Plant Preview" className="w-full h-full object-cover rounded-xl" />
            ) : (
              <>
                <Upload size={48} className="text-indigo-300 mb-2" />
                <span className="text-sm text-indigo-200">Drag & Drop Plant Image</span>
              </>
            )}
            {analyzing && (
              <div className="absolute inset-0 bg-indigo-900/60 backdrop-blur-sm rounded-xl flex flex-col items-center justify-center">
                <Loader2 className="animate-spin text-white mb-2" size={32} />
                <span className="text-white text-xs font-bold">AI ANALYZING...</span>
              </div>
            )}
          </div>
        </div>
        {/* Background blobs */}
        <div className="absolute -top-24 -right-24 w-64 h-64 bg-indigo-400 rounded-full blur-3xl opacity-20"></div>
        <div className="absolute -bottom-24 -left-24 w-64 h-64 bg-purple-400 rounded-full blur-3xl opacity-20"></div>
      </div>

      {result && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="lg:col-span-1 bg-white p-6 rounded-2xl border border-slate-100 shadow-sm h-fit">
            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4">Health Assessment</h3>
            <div className="flex items-center gap-3 mb-6">
              {result.status.toLowerCase().includes('healthy') ? (
                <div className="p-2 bg-emerald-100 text-emerald-600 rounded-full">
                  <CheckCircle2 size={24} />
                </div>
              ) : (
                <div className="p-2 bg-amber-100 text-amber-600 rounded-full">
                  <AlertCircle size={24} />
                </div>
              )}
              <span className="text-2xl font-bold text-slate-800">{result.status}</span>
            </div>
            <p className="text-slate-600 leading-relaxed italic">
              "{result.diagnosis}"
            </p>
          </div>

          <div className="lg:col-span-2 bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-6">AI Recommendations</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {result.recommendations.map((rec, i) => (
                <div key={i} className="flex gap-4 p-4 bg-slate-50 rounded-xl border border-slate-100">
                  <div className="bg-white w-8 h-8 rounded-full flex items-center justify-center font-bold text-indigo-600 shadow-sm flex-shrink-0">
                    {i + 1}
                  </div>
                  <p className="text-slate-700 text-sm leading-relaxed">{rec}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SmartAdvisor;

