import React from 'react';
import { X, Sparkles, Calendar, Check, Loader2, Package } from 'lucide-react';
import { PlanningSuggestion } from '../types';

interface PlanningModalProps {
  isOpen: boolean;
  onClose: () => void;
  loading: boolean;
  suggestions: PlanningSuggestion[];
  onConfirm: (suggestion: PlanningSuggestion) => void;
}

const PlanningModal: React.FC<PlanningModalProps> = ({ isOpen, onClose, loading, suggestions, onConfirm }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={onClose}></div>
      <div className="bg-white rounded-3xl w-full max-w-2xl max-h-[90vh] overflow-hidden shadow-2xl relative z-10 flex flex-col">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-emerald-50/50">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-emerald-100 text-emerald-600 rounded-lg">
              <Sparkles size={20} />
            </div>
            <div>
              <h3 className="text-xl font-bold text-slate-900">AI Planting Suggestions</h3>
              <p className="text-sm text-slate-500">Optimized based on inventory & active crops</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white rounded-full transition-colors text-slate-400 hover:text-slate-600">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {loading ? (
            <div className="flex flex-col items-center justify-center py-20 space-y-4 text-center">
              <div className="relative">
                <Loader2 size={48} className="text-emerald-500 animate-spin" />
                <Sparkles size={24} className="text-amber-400 absolute -top-2 -right-2 animate-pulse" />
              </div>
              <div>
                <p className="font-bold text-slate-700 text-lg">AI is analyzing your farm...</p>
                <p className="text-slate-500 text-sm">Calculating resource efficiency and growth windows.</p>
              </div>
            </div>
          ) : suggestions.length > 0 ? (
            suggestions.map((s, i) => (
              <div key={i} className="border border-slate-100 bg-slate-50/50 rounded-2xl p-5 hover:border-emerald-200 hover:bg-white transition-all group">
                <div className="flex justify-between items-start mb-3">
                  <div>
                    <h4 className="text-lg font-bold text-slate-800">{s.cropName}</h4>
                    <div className="flex items-center gap-2 text-sm text-emerald-600 font-medium">
                      <Calendar size={14} />
                      Suggested: {s.suggestedDate}
                    </div>
                  </div>
                  <button 
                    onClick={() => onConfirm(s)}
                    className="p-2 bg-emerald-600 text-white rounded-xl hover:bg-emerald-700 transition-colors shadow-sm"
                  >
                    <Check size={18} />
                  </button>
                </div>

                <p className="text-sm text-slate-600 leading-relaxed mb-4">
                  {s.reasoning}
                </p>

                <div className="flex flex-wrap gap-2">
                  {s.requiredResources.map((res, idx) => (
                    <span key={idx} className="flex items-center gap-1.5 px-3 py-1 bg-white border border-slate-100 text-slate-500 text-xs font-medium rounded-lg">
                      <Package size={12} />
                      {res}
                    </span>
                  ))}
                </div>
              </div>
            ))
          ) : (
            <div className="text-center py-10">
              <p className="text-slate-500">No suggestions available at this time.</p>
            </div>
          )}
        </div>

        <div className="p-4 bg-slate-50 border-t border-slate-100 text-center text-[10px] text-slate-400 uppercase tracking-widest font-bold">
          mPonics Intelligent MRP System
        </div>
      </div>
    </div>
  );
};

