import React, { useState } from 'react';
import { 
  LayoutDashboard, 
  Package, 
  Sprout, 
  BrainCircuit, 
  CalendarClock, 
  Settings,
  Bell,
  Menu,
  X,
  Search,
  Plus
} from 'lucide-react';
import Dashboard from './components/Dashboard';
import CropManagement from './components/CropManagement';
import SmartAdvisor from './components/SmartAdvisor';
import PlanningModal from './components/PlanningModal';
import { getSmartPlanning } from './services/geminiService';
import { Crop, InventoryItem, PlanningSuggestion } from './types';

const INITIAL_CROPS: Crop[] = [
  { id: '1', name: 'Butterhead Lettuce', variety: 'Green', plantedDate: '2024-05-01', expectedHarvestDate: '2024-05-30', status: 'Vegetative', health: 92, yield_estimate: 2.5 },
  { id: '2', name: 'Cherry Tomato', variety: 'Sweet Million', plantedDate: '2024-04-15', expectedHarvestDate: '2024-06-15', status: 'Flowering', health: 88, yield_estimate: 12.0 },
  { id: '3', name: 'Thai Basil', variety: 'Siam Queen', plantedDate: '2024-05-10', expectedHarvestDate: '2024-06-05', status: 'Seedling', health: 95, yield_estimate: 1.2 },
  { id: '4', name: 'Spinach', variety: 'Bloomsdale', plantedDate: '2024-05-05', expectedHarvestDate: '2024-06-10', status: 'Vegetative', health: 90, yield_estimate: 3.0 },
];

const INITIAL_INVENTORY: InventoryItem[] = [
  { id: '1', name: 'Nutrient Mix A', category: 'Nutrient', quantity: 85, unit: '%', threshold: 20 },
  { id: '2', name: 'Nutrient Mix B', category: 'Nutrient', quantity: 72, unit: '%', threshold: 20 },
  { id: '3', name: 'pH Down Solution', category: 'Nutrient', quantity: 30, unit: '%', threshold: 25 },
  { id: '4', name: 'Rockwool Cubes', category: 'Substrate', quantity: 45, unit: 'pcs', threshold: 10 },
  { id: '5', name: 'Kale Seeds', category: 'Seed', quantity: 500, unit: 'pcs', threshold: 100 },
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'crops' | 'inventory' | 'advisor'>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [crops, setCrops] = useState<Crop[]>(INITIAL_CROPS);
  const [inventory, setInventory] = useState<InventoryItem[]>(INITIAL_INVENTORY);

  // AI Planning State
  const [isPlanningModalOpen, setIsPlanningModalOpen] = useState(false);
  const [isPlanningLoading, setIsPlanningLoading] = useState(false);
  const [planningSuggestions, setPlanningSuggestions] = useState<PlanningSuggestion[]>([]);

  const navigation = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'crops', label: 'Crops', icon: Sprout },
    { id: 'inventory', label: 'Inventory', icon: Package },
    { id: 'advisor', label: 'AI Advisor', icon: BrainCircuit },
  ];

  const handleStartPlanning = async () => {
    setIsPlanningModalOpen(true);
    setIsPlanningLoading(true);
    setPlanningSuggestions([]);
    try {
      const suggestions = await getSmartPlanning(inventory, crops);
      setPlanningSuggestions(suggestions);
    } catch (error) {
      console.error("AI Planning failed", error);
    } finally {
      setIsPlanningLoading(false);
    }
  };

  const handleConfirmSuggestion = (suggestion: PlanningSuggestion) => {
    const newCrop: Crop = {
      id: Math.random().toString(36).substr(2, 9),
      name: suggestion.cropName,
      variety: 'Suggested Variety',
      plantedDate: new Date().toISOString().split('T')[0],
      expectedHarvestDate: suggestion.suggestedDate,
      status: 'Seedling',
      health: 100,
      yield_estimate: 0
    };
    setCrops([...crops, newCrop]);
    setIsPlanningModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex overflow-hidden">
      {/* Sidebar */}
      <aside 
        className={`${
          isSidebarOpen ? 'w-64' : 'w-20'
        } transition-all duration-300 bg-white border-r border-slate-200 hidden md:flex flex-col z-30`}
      >
        <div className="p-6 flex items-center gap-3">
          <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center text-white font-black">
            mP
          </div>
          {isSidebarOpen && <span className="font-bold text-xl text-slate-800 tracking-tight">mPonics <span className="text-emerald-600">MRP</span></span>}
        </div>

        <nav className="flex-1 px-4 space-y-1">
          {navigation.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl transition-all ${
                activeTab === item.id 
                  ? 'bg-emerald-50 text-emerald-600 font-bold shadow-sm border border-emerald-100' 
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-700'
              }`}
            >
              <item.icon size={22} strokeWidth={activeTab === item.id ? 2.5 : 2} />
              {isSidebarOpen && <span className="text-sm uppercase tracking-wide">{item.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100">
          <button className="w-full flex items-center gap-4 px-4 py-3 rounded-xl text-slate-500 hover:bg-slate-50">
            <Settings size={22} />
            {isSidebarOpen && <span className="text-sm">Settings</span>}
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-100 flex items-center justify-between px-6 z-20 sticky top-0">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              className="text-slate-400 hover:text-slate-600 p-2 rounded-lg hover:bg-slate-50 transition-colors"
            >
              <Menu size={20} />
            </button>
            <div className="hidden sm:flex items-center bg-slate-50 rounded-xl px-4 py-1.5 border border-slate-200 w-64">
              <Search size={16} className="text-slate-400 mr-2" />
              <input 
                type="text" 
                placeholder="Search..." 
                className="bg-transparent border-none outline-none text-sm text-slate-600 w-full"
              />
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div className="relative">
              <button className="text-slate-400 hover:text-slate-600 p-2 rounded-lg hover:bg-slate-50">
                <Bell size={20} />
              </button>
              <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
            </div>
            <div className="h-8 w-px bg-slate-100 mx-2"></div>
            <div className="flex items-center gap-3">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold text-slate-700">Farm Manager</p>
                <p className="text-xs text-slate-500">Facility #04</p>
              </div>
              <div className="w-10 h-10 rounded-full bg-slate-200 overflow-hidden border-2 border-white shadow-sm">
                <img src="https://picsum.photos/40/40?random=1" alt="Avatar" />
              </div>
            </div>
          </div>
        </header>

        {/* Scrollable Viewport */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto">
            {activeTab === 'dashboard' && <Dashboard crops={crops} inventory={inventory} />}
            {activeTab === 'crops' && <CropManagement crops={crops} onAddCrop={handleStartPlanning} />}
            {activeTab === 'advisor' && <SmartAdvisor />}

            {activeTab === 'inventory' && (
              <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
                <div className="flex justify-between items-center mb-8">
                   <div>
                    <h2 className="text-2xl font-bold text-slate-900">Inventory Status</h2>
                    <p className="text-slate-500">Monitor and reorder production materials.</p>
                  </div>
                  <button className="bg-slate-900 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2">
                    <Package size={18} />
                    New Order
                  </button>
