import { GoogleGenAI, Type } from "@google/genai";
import { MenuItem, Client, AIRecommendation } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const optimizeMenuDescription = async (itemName: string, currentDesc: string) => {
  const ai = getAI();
  const prompt = `You are a world-class culinary copywriter. Rewrite this catering menu description to be incredibly appetizing, high-end, and persuasive. Use vivid sensory language.

  Dish Name: ${itemName}
  Current Description: ${currentDesc}

  Return only the new description.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt
  });

  return response.text;
};

export const getSalesOutreachSuggestions = async (clients: Client[]) => {
  const ai = getAI();
  const prompt = `Analyze these catering clients and suggest who to contact today to boost sales. Look for patterns (e.g., someone who hasn't ordered in a while but used to order weekly).

  Clients: ${JSON.stringify(clients)}

  Provide exactly 3 high-potential recommendations.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            clientName: { type: Type.STRING },
            reason: { type: Type.STRING },
            suggestedAction: { type: Type.STRING },
            pitch: { type: Type.STRING, description: "A personalized message to send to the client" }
          },
          required: ["clientName", "reason", "suggestedAction", "pitch"]
        }
      }
    }
  });

  return JSON.parse(response.text || "[]") as AIRecommendation[];
};

import React, { useState } from 'react';
