 * Diagnoses a plant image using Gemini AI to detect diseases, pests, or deficiencies.
 * Used by the SmartAdvisor component.
 */
export const diagnosePlantImage = async (base64Image: string): Promise<AnalysisResult> => {
  const ai = getAI();
  // Extract base64 data and mime type from the data URL
  const base64Data = base64Image.split(',').pop() || "";
  const mimeType = base64Image.match(/:(.*?);/)?.[1] || 'image/jpeg';

  const imagePart = {
    inlineData: {
      mimeType: mimeType,
      data: base64Data,
    },
  };
  const textPart = {
    text: "Analyze this plant image. Identify any diseases, pests, or nutrient deficiencies. Provide a status (e.g., 'Healthy', 'Pest Detected', 'Nutrient Deficiency'), a brief diagnosis, and 3 actionable recommendations."
  };

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts: [imagePart, textPart] },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          status: { type: Type.STRING },
          diagnosis: { type: Type.STRING },
          recommendations: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["status", "diagnosis", "recommendations"]
      }
    }
  });

  try {
    return JSON.parse(response.text || "{}") as AnalysisResult;
  } catch (error) {
    console.error("Failed to parse AI response", error);
    return {
      status: "Unknown",
      diagnosis: "Failed to analyze image content.",
      recommendations: ["Please try again with a clearer image."]
    };
  }
};

