import React, { useState, useMemo } from 'react';
import { BrainCircuit, Send, Calendar, Star, Sparkles, Loader2, Filter, UserCheck, AlertCircle, TrendingUp } from 'lucide-react';
import { getSalesOutreachSuggestions } from '../services/geminiService';
import { Client, AIRecommendation, ClientSegment } from '../types';

interface SmartOutreachProps {
  clients: Client[];
}

const SmartOutreach: React.FC<SmartOutreachProps> = ({ clients }) => {
  const [loading, setLoading] = useState(false);
  const [recommendations, setRecommendations] = useState<AIRecommendation[]>([]);
  const [filter, setFilter] = useState<ClientSegment | 'All'>('All');

  // Logic for segmentation
  const segmentedClients = useMemo(() => {
    return clients.map(client => {
      const lastOrder = new Date(client.lastOrderDate);
      const daysSinceLastOrder = (new Date().getTime() - lastOrder.getTime()) / (1000 * 3600 * 24);

      let segment: ClientSegment = 'Potential Upsell';
      if (client.totalSpent > 10000000) segment = 'High Value';
      else if (daysSinceLastOrder > 30) segment = 'Lapsed';

      return { ...client, segment };
    });
  }, [clients]);

  const filteredClients = useMemo(() => {
    if (filter === 'All') return segmentedClients;
    return segmentedClients.filter(c => c.segment === filter);
  }, [segmentedClients, filter]);

  const generateInsights = async () => {
    setLoading(true);
    try {
      const res = await getSalesOutreachSuggestions(segmentedClients);
      setRecommendations(res);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const getSegmentStyles = (segment: ClientSegment) => {
    switch (segment) {
      case 'High Value': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'Lapsed': return 'bg-rose-100 text-rose-700 border-rose-200';
      case 'Potential Upsell': return 'bg-indigo-100 text-indigo-700 border-indigo-200';
    }
  };

  const getSegmentIcon = (segment: ClientSegment) => {
    switch (segment) {
      case 'High Value': return <TrendingUp size={14} />;
      case 'Lapsed': return <AlertCircle size={14} />;
      case 'Potential Upsell': return <UserCheck size={14} />;
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-3xl p-8 text-white relative overflow-hidden shadow-xl">
        <div className="relative z-10">
          <div className="flex items-center gap-3 mb-4">
            <div className="p-2 bg-indigo-500/30 rounded-xl">
              <BrainCircuit size={24} />
            </div>
            <span className="text-sm font-bold uppercase tracking-widest text-indigo-200">Sales Catalyst AI</span>
          </div>
          <h2 className="text-3xl font-bold mb-4">Proactive Customer Outreach</h2>
          <p className="text-indigo-100 max-w-xl mb-8 leading-relaxed">
            Sistem kami telah mengelompokkan pelanggan Anda. Gunakan AI untuk membuat strategi pendekatan yang tepat bagi tiap segmen.
          </p>
          <button 
            onClick={generateInsights}
            disabled={loading}
            className="bg-white text-indigo-700 px-8 py-3 rounded-xl font-bold hover:bg-indigo-50 transition-all flex items-center gap-3 shadow-lg shadow-indigo-900/20 disabled:opacity-70"
          >
            {loading ? <Loader2 className="animate-spin" size={20} /> : <Sparkles size={20} />}
            Analyze Segments & Generate Strategy
          </button>
        </div>
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-20 -mt-20 blur-3xl"></div>
      </div>

      <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
          <h3 className="text-lg font-bold flex items-center gap-2">
            <Filter size={20} className="text-slate-400" />
            Customer Segments
          </h3>
          <div className="flex flex-wrap gap-2">
            {(['All', 'High Value', 'Lapsed', 'Potential Upsell'] as const).map(s => (
              <button
                key={s}
                onClick={() => setFilter(s)}
                className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${
                  filter === s 
                    ? 'bg-slate-900 text-white border-slate-900' 
                    : 'bg-white text-slate-500 border-slate-200 hover:border-slate-300'
                }`}
              >
                {s}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredClients.map(client => (
            <div key={client.id} className="p-4 border border-slate-50 rounded-2xl bg-slate-50/30 hover:bg-white hover:border-slate-200 transition-all group">
              <div className="flex justify-between items-start mb-3">
                <div className="w-10 h-10 bg-white rounded-full flex items-center justify-center font-bold text-slate-400 border border-slate-100 group-hover:border-indigo-200 group-hover:text-indigo-500 transition-colors">
                  {client.name.charAt(0)}
                </div>
                <div className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-bold border uppercase tracking-wider ${getSegmentStyles(client.segment!)}`}>
                  {getSegmentIcon(client.segment!)}
                  {client.segment}
                </div>
              </div>
