import { GoogleGenAI, Type } from "@google/genai";
import { MenuItem, Client, AIRecommendation, AnalysisResult } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const optimizeMenuDescription = async (itemName: string, currentDesc: string) => {
  const ai = getAI();

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Nama Hidangan: ${itemName}\nDeskripsi Saat Ini: ${currentDesc}`,
    config: {
      systemInstruction: "Anda adalah copywriter kuliner kelas dunia untuk layanan katering mewah. Tugas Anda adalah menulis ulang deskripsi hidangan agar terlihat sangat menggugah selera, menggunakan bahasa sensorik yang hidup (tekstur, aroma, catatan rasa). Pastikan deskripsi antara 20-40 kata. Fokus pada bahan-bahan premium dan teknik memasak. Kembalikan HANYA teks deskripsi yang ditulis ulang dalam BAHASA INDONESIA tanpa awalan atau tanda kutip apa pun.",
      temperature: 0.8,
    },
  });

  return response.text;
};

export const getSalesOutreachSuggestions = async (clients: Client[]) => {
  const ai = getAI();
  const prompt = `Analyze these catering clients and suggest who to contact today to boost sales. 
  The clients are already segmented into:
  - 'High Value': Top tier spenders.
  - 'Lapsed': Haven't ordered in a month.
  - 'Potential Upsell': Regulars who could buy more.

  Clients: ${JSON.stringify(clients)}

  Provide exactly 3 high-potential recommendations. Tailor the 'pitch' based on their segment. 
  For Lapsed clients, focus on "we miss you" or new menu items. 
  For High Value, focus on "exclusive loyalty offers" or premium corporate packages.

  Return JSON in the specified format. Use Indonesian for the 'pitch' and 'reason' fields.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            clientName: { type: Type.STRING },
            reason: { type: Type.STRING, description: "Alasan mengapa klien ini dipilih." },
            suggestedAction: { type: Type.STRING },
            pitch: { type: Type.STRING, description: "Pesan personalisasi dalam Bahasa Indonesia" }
          },
          required: ["clientName", "reason", "suggestedAction", "pitch"]
        }
      }
    }
  });

  return JSON.parse(response.text || "[]") as AIRecommendation[];
};

export const diagnosePlantImage = async (base64Image: string) => {
  const ai = getAI();
  const base64Data = base64Image.split(',')[1] || base64Image;
  const mimeType = base64Image.split(';')[0].split(':')[1] || 'image/jpeg';

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Data,
            mimeType: mimeType,
          },
        },
        {
          text: `Analyze this plant image for an indoor hydroponic farm (mPonics). 
          Identify the plant, assess its health, and diagnose any issues.
          Provide a status, a diagnosis, and actionable recommendations in JSON format. Use Indonesian for all text fields.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          status: { type: Type.STRING, description: "Status kesehatan singkat." },
          diagnosis: { type: Type.STRING, description: "Diagnosis klinis detail." },
          recommendations: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "Saran tindakan untuk optimasi pertumbuhan."
          }
        },
        required: ["status", "diagnosis", "recommendations"]
      }
    }
  });

  return JSON.parse(response.text || "{}") as AnalysisResult;
};

