  const [formData, setFormData] = useState<Partial<MenuItem>>({
    name: '',
    category: 'Main Course',
    price: 0,
    cost: 0,
    description: '',
    imageUrl: ''
  });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAIUIOptimize = async (item: MenuItem) => {
    setOptimizingId(item.id);
    try {
      const newDesc = await optimizeMenuDescription(item.name, item.description);
      if (newDesc) {
        const updatedMenu = menu.map(m => 
          m.id === item.id ? { ...m, description: newDesc.trim() } : m
        );
        onUpdateMenu(updatedMenu);
        setSuccessId(item.id);
        setTimeout(() => setSuccessId(null), 3000);
      }
    } catch (error) {
      console.error("Optimization failed", error);
    } finally {
      setOptimizingId(null);
    }
  };

  const handleCreateDish = () => {
    if (!formData.name || !formData.price || !formData.imageUrl) {
      alert("Mohon isi nama, harga, dan unggah gambar.");
      return;
    }

    const newDish: MenuItem = {
      ...formData as MenuItem,
      id: Date.now().toString(),
      salesCount: 0,
    };

    onUpdateMenu([newDish, ...menu]);
    setIsModalOpen(false);
    setFormData({
      name: '',
      category: 'Main Course',
      price: 0,
      cost: 0,
      description: '',
      imageUrl: ''
    });
  };

  const generateAIDescription = async () => {
    if (!formData.name) return;
    setIsAiLoading(true);
    try {
      const desc = await optimizeMenuDescription(formData.name, "Buat deskripsi menu yang menggugah selera dalam Bahasa Indonesia.");
      setFormData(prev => ({ ...prev, description: desc.trim() }));
    } catch (err) {
      console.error(err);
    } finally {
      setIsAiLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Elite Menu</h2>
          <p className="text-slate-500">Rancang menu Anda dan optimalkan daya tarik penjualan.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-xl flex items-center gap-2 transition-all shadow-lg shadow-slate-200"
        >
          <Plus size={20} />
          Create Dish
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {menu.map((item) => (
          <div key={item.id} className="bg-white rounded-2xl border border-slate-100 overflow-hidden flex flex-col sm:flex-row group hover:shadow-xl hover:shadow-slate-100 transition-all">
            <div className="sm:w-48 h-48 sm:h-auto overflow-hidden">
              <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
            </div>
            <div className="flex-1 p-6 flex flex-col justify-between relative">
              <div>
                <div className="flex justify-between items-start mb-2">
                  <h3 className="text-lg font-bold text-slate-800">{item.name}</h3>
                  <span className="text-emerald-600 font-bold">Rp {(item.price/1000).toFixed(0)}k</span>
                </div>
                <div className="relative">
                  <p className={`text-slate-500 text-sm line-clamp-3 mb-4 italic transition-all duration-700 ${successId === item.id ? 'text-amber-600 bg-amber-50 rounded-lg p-1' : ''}`}>
                    {item.description}
                  </p>
                  {successId === item.id && (
                    <div className="absolute -top-2 -right-2 bg-amber-500 text-white p-1 rounded-full animate-bounce">
                      <CheckCircle size={12} />
                    </div>
                  )}
                </div>
                <div className="flex items-center gap-3">
                  <span className="px-2 py-1 bg-slate-100 text-slate-500 rounded text-[10px] font-bold uppercase">{item.category}</span>
                  <span className="text-xs text-slate-400">{item.salesCount} terjual</span>
                </div>
              </div>

              <div className="mt-6 flex items-center gap-2">
                <button 
                  onClick={() => handleAIUIOptimize(item)}
                  disabled={!!optimizingId}
                  className={`flex-1 text-xs font-bold py-2 rounded-lg flex items-center justify-center gap-2 transition-all ${
                    optimizingId === item.id 
                      ? 'bg-amber-100 text-amber-700 animate-pulse' 
                      : 'bg-amber-50 hover:bg-amber-100 text-amber-700'
                  } disabled:opacity-50`}
                >
                  {optimizingId === item.id ? (
                    <Loader2 size={14} className="animate-spin" />
                  ) : (
                    <Sparkles size={14} />
                  )}
                  {optimizingId === item.id ? 'AI Menulis...' : 'AI Optimize'}
                </button>
                <button className="p-2 text-slate-300 hover:text-rose-500 transition-colors" onClick={() => onUpdateMenu(menu.filter(m => m.id !== item.id))}>
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Create Dish Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
          <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-200">
