import { MenuItem } from '../types';
import { optimizeMenuDescription } from '../services/geminiService';

interface MenuManagerProps {
  menu: MenuItem[];
  onUpdateMenu: (menu: MenuItem[]) => void;
}

const MenuManager: React.FC<MenuManagerProps> = ({ menu, onUpdateMenu }) => {
  const [optimizingId, setOptimizingId] = useState<string | null>(null);
  const [successId, setSuccessId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<MenuItem>>({
    name: '',
    category: 'Main Course',
    price: 0,
    cost: 0,
    description: '',
    imageUrl: ''
  });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAIUIOptimize = async (item: MenuItem) => {
    setOptimizingId(item.id);
    try {
      const newDesc = await optimizeMenuDescription(item.name, item.description);
      if (newDesc) {
        const updatedMenu = menu.map(m => 
          m.id === item.id ? { ...m, description: newDesc.trim() } : m
        );
        onUpdateMenu(updatedMenu);
        setSuccessId(item.id);
        setTimeout(() => setSuccessId(null), 3000);
      }
    } catch (error) {
      console.error("Optimization failed", error);
    } finally {
      setOptimizingId(null);
    }
  };

  const handleCreateDish = () => {
    if (!formData.name || !formData.price || !formData.imageUrl) {
      alert("Mohon isi nama, harga, dan unggah gambar.");
      return;
    }

    const newDish: MenuItem = {
      ...formData as MenuItem,
      id: Date.now().toString(),
      salesCount: 0,
    };

    onUpdateMenu([newDish, ...menu]);
    setIsModalOpen(false);
    setFormData({
      name: '',
      category: 'Main Course',
      price: 0,
      cost: 0,
      description: '',
      imageUrl: ''
    });
  };

  const generateAIDescription = async () => {
    if (!formData.name) return;
    setIsAiLoading(true);
    try {
      const desc = await optimizeMenuDescription(formData.name, "Buat deskripsi menu yang menggugah selera dalam Bahasa Indonesia.");
      setFormData(prev => ({ ...prev, description: desc.trim() }));
    } catch (err) {
      console.error(err);
    } finally {
      setIsAiLoading(false);
    }
