          >
            <Plus size={20} />
            Tambah Menu
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {menu.map((item) => (
          <div key={item.id} className="bg-white rounded-2xl border border-slate-100 overflow-hidden flex flex-col sm:flex-row group hover:shadow-xl hover:shadow-slate-100 transition-all">
            <div className="sm:w-48 h-48 sm:h-auto overflow-hidden">
              <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
            </div>
            <div className="flex-1 p-6 flex flex-col justify-between relative">
              <div>
