import React, { useState, useMemo } from 'react';
import { Search, ShoppingCart, MessageCircle, ChevronRight, Star, Info } from 'lucide-react';
import { MenuItem } from '../types';

interface PublicMenuProps {
  menu: MenuItem[];
}

const PublicMenu: React.FC<PublicMenuProps> = ({ menu }) => {
  const [activeCategory, setActiveCategory] = useState<string>('Semua');
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<{ [key: string]: number }>({});

  const categories = ['Semua', ...Array.from(new Set(menu.map(m => m.category)))];

  const filteredMenu = useMemo(() => {
    return menu.filter(item => {
      const matchesCategory = activeCategory === 'Semua' || item.category === activeCategory;
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [menu, activeCategory, searchQuery]);

  const addToCart = (id: string) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: string) => {
    if (!cart[id]) return;
    const newCart = { ...cart };
    if (newCart[id] === 1) delete newCart[id];
    else newCart[id]--;
    setCart(newCart);
  };

  // Fix: Explicitly typecast values to avoid 'unknown' errors in reduce operations
  const cartCount = (Object.values(cart) as number[]).reduce((a, b) => a + b, 0);
  const cartTotal = (Object.entries(cart) as [string, number][]).reduce((total, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    // Fix: qty is now correctly typed as number through explicit cast of Object.entries
    return total + (item ? item.price * qty : 0);
  }, 0);

  return (
    <div className="min-h-screen bg-white text-slate-900 pb-32">
      {/* Hero Header */}
      <div className="bg-slate-900 text-white p-8 pt-12 rounded-b-[3rem] shadow-2xl relative overflow-hidden">
        <div className="relative z-10">
          <div className="flex justify-between items-center mb-6">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-amber-500 rounded-lg flex items-center justify-center font-black text-xs">CE</div>
              <span className="font-bold tracking-tight">CaterElite Digital Menu</span>
            </div>
            <button className="p-2 bg-white/10 rounded-full">
              <Info size={18} />
            </button>
          </div>
          <h1 className="text-3xl font-bold mb-2">Selamat Datang!</h1>
          <p className="text-slate-400 text-sm">Pilih hidangan katering terbaik untuk acara spesial Anda.</p>
        </div>
        <div className="absolute -bottom-12 -right-12 w-48 h-48 bg-amber-500/20 rounded-full blur-3xl"></div>
      </div>

      {/* Search & Categories */}
      <div className="px-6 -mt-6 relative z-20">
        <div className="bg-white rounded-2xl shadow-xl border border-slate-100 p-2 flex items-center mb-8">
          <Search size={20} className="text-slate-400 ml-3" />
          <input 
            type="text" 
            placeholder="Cari hidangan favorit..." 
            className="flex-1 px-4 py-3 outline-none text-sm"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`px-6 py-2.5 rounded-full text-xs font-bold whitespace-nowrap transition-all ${
                activeCategory === cat 
                  ? 'bg-amber-500 text-white shadow-lg shadow-amber-200 scale-105' 
                  : 'bg-slate-100 text-slate-500 hover:bg-slate-200'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      {/* Menu Grid */}
      <div className="px-6 mt-4 grid grid-cols-1 sm:grid-cols-2 gap-6">
        {filteredMenu.map(item => (
          <div key={item.id} className="group animate-in fade-in zoom-in-95 duration-500">
            <div className="relative aspect-[4/3] rounded-3xl overflow-hidden shadow-lg mb-4">
              <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
              <div className="absolute top-4 right-4 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider text-slate-800">
                {item.category}
              </div>
            </div>
            <div className="flex justify-between items-start">
              <div>
                <h3 className="font-bold text-lg text-slate-800">{item.name}</h3>
                <p className="text-xs text-slate-500 mt-1 line-clamp-2 italic">{item.description}</p>
                <p className="text-amber-600 font-black text-xl mt-2">Rp {(item.price/1000).toFixed(0)}k</p>
              </div>
              <div className="flex flex-col items-center bg-slate-100 rounded-2xl p-1">
                <button 
                  onClick={() => addToCart(item.id)}
                  className="w-10 h-10 bg-white shadow-sm rounded-xl flex items-center justify-center text-slate-800 hover:bg-amber-500 hover:text-white transition-all active:scale-90"
                >
                  <ShoppingCart size={18} />
                </button>
                {/* Fix: Explicit check and cast for cart item quantity to resolve unknown type error */}
                {(cart[item.id] as number || 0) > 0 && (
                  <span className="text-xs font-bold py-1">{cart[item.id]}</span>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Floating Cart Button */}
      {cartCount > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[90%] max-w-md animate-in slide-in-from-bottom-8 duration-500 z-50">
          <div className="bg-slate-900 text-white rounded-[2rem] p-4 pl-6 flex items-center justify-between shadow-2xl border border-white/10">
            <div className="flex items-center gap-4">
              <div className="relative">
                <ShoppingCart size={24} />
                <span className="absolute -top-2 -right-2 bg-amber-500 text-[10px] font-black w-5 h-5 flex items-center justify-center rounded-full border-2 border-slate-900">
                  {cartCount}
                </span>
              </div>
              <div>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-none">Total Estimasi</p>
                <p className="text-lg font-black text-amber-500">Rp {(cartTotal/1000).toFixed(0)}k</p>
              </div>
            </div>
            <button 
              className="bg-emerald-500 hover:bg-emerald-600 text-white px-6 py-3 rounded-2xl font-bold flex items-center gap-2 transition-all active:scale-95"
              onClick={() => alert('Pesanan akan diteruskan ke WhatsApp Admin!')}
            >
              <MessageCircle size={20} />
              Pesan
            </button>
          </div>
        </div>
      )}

      {filteredMenu.length === 0 && (
        <div className="py-20 text-center">
          <p className="text-slate-400 italic">Menu tidak ditemukan...</p>
        </div>
      )}
    </div>
  );
};

