          CE
        </div>
        <div className={`overflow-hidden transition-all duration-500 ${isOpen ? 'w-auto opacity-100' : 'w-0 opacity-0'}`}>
          <span className="font-bold text-xl text-slate-800 tracking-tight whitespace-nowrap">
            Cater<span className="text-amber-500">Elite</span>
          </span>
        </div>
      </div>

      <nav className="flex-1 px-4 space-y-1">
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id)}
            className={`w-full group relative flex items-center px-4 py-3.5 rounded-xl transition-all duration-300 ${
              activeTab === item.id 
                ? 'bg-amber-500 text-white font-bold shadow-md shadow-amber-200' 
                : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'
