interface MenuManagerProps {
  menu: MenuItem[];
  onUpdateMenu: (menu: MenuItem[]) => void;
}

const MenuManager: React.FC<MenuManagerProps> = ({ menu, onUpdateMenu }) => {
  const [optimizingId, setOptimizingId] = useState<string | null>(null);
  const [successId, setSuccessId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<MenuItem>>({
    name: '',
    category: 'Main Course',
    price: 0,
    cost: 0,
    description: '',
    imageUrl: ''
  });

  const handleCopyLink = () => {
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
    // In a real app: navigator.clipboard.writeText("https://caterelite.ai/kedai-anda");
  };

  const handleAIUIOptimize = async (item: MenuItem) => {
    setOptimizingId(item.id);
    try {
      const newDesc = await optimizeMenuDescription(item.name, item.description);
      if (newDesc) {
        const updatedMenu = menu.map(m => 
          m.id === item.id ? { ...m, description: newDesc.trim() } : m
        );
        onUpdateMenu(updatedMenu);
        setSuccessId(item.id);
        setTimeout(() => setSuccessId(null), 3000);
      }
    } catch (error) {
      console.error("Optimization failed", error);
    } finally {
      setOptimizingId(null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Manajemen Menu</h2>
          <p className="text-sm text-slate-500 mt-1">Atur hidangan katering dan bagikan ke pelanggan.</p>
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
          <button 
            onClick={() => setIsShareModalOpen(true)}
            className="flex-1 sm:flex-none bg-amber-50 text-amber-700 border border-amber-200 px-5 py-2.5 rounded-xl flex items-center justify-center gap-2 hover:bg-amber-100 transition-all font-bold text-sm"
          >
            <Share2 size={18} />
            Bagikan Menu
          </button>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="flex-1 sm:flex-none bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-slate-200 font-bold text-sm"
          >
            <Plus size={20} />
            Tambah
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {menu.map((item) => (
          <div key={item.id} className="bg-white rounded-3xl border border-slate-100 overflow-hidden flex flex-col sm:flex-row group hover:shadow-xl hover:shadow-slate-100 transition-all">
            <div className="sm:w-48 h-48 sm:h-auto overflow-hidden shrink-0">
              <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
            </div>
            <div className="flex-1 p-6 flex flex-col justify-between relative">
              <div>
                <div className="flex justify-between items-start mb-2">
                  <h3 className="text-lg font-bold text-slate-800 group-hover:text-amber-600 transition-colors">{item.name}</h3>
                  <span className="text-amber-600 font-black">Rp {(item.price/1000).toFixed(0)}k</span>
                </div>
                <p className={`text-slate-500 text-xs line-clamp-3 mb-4 italic leading-relaxed transition-all duration-700 ${successId === item.id ? 'text-amber-600 bg-amber-50 rounded-lg p-2' : ''}`}>
                  {item.description}
                </p>
                <div className="flex items-center gap-3">
                  <span className="px-2 py-1 bg-slate-50 text-slate-400 rounded-lg text-[9px] font-black uppercase tracking-widest border border-slate-100">{item.category}</span>
                  <span className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">{item.salesCount} Penjualan</span>
                </div>
              </div>

              <div className="mt-6 flex items-center gap-2">
                <button 
                  onClick={() => handleAIUIOptimize(item)}
                  disabled={!!optimizingId}
                  className={`flex-1 text-[10px] font-black uppercase tracking-widest py-3 rounded-xl flex items-center justify-center gap-2 transition-all border ${
                    optimizingId === item.id 
