import React, { useState, useMemo } from 'react';
import { 
  BrainCircuit, Send, Calendar, Star, Sparkles, Loader2, 
  Filter, UserCheck, AlertCircle, TrendingUp, Search, 
  Mail, ArrowUpRight, ChevronRight, UserCircle 
} from 'lucide-react';
import { getSalesOutreachSuggestions } from '../services/geminiService';
import { Client, AIRecommendation, ClientSegment } from '../types';

interface SmartOutreachProps {
  clients: Client[];
}

const SmartOutreach: React.FC<SmartOutreachProps> = ({ clients }) => {
  const [loading, setLoading] = useState(false);
  const [recommendations, setRecommendations] = useState<AIRecommendation[]>([]);
  const [filter, setFilter] = useState<ClientSegment | 'All'>('All');
  const [searchQuery, setSearchQuery] = useState('');

  // Logic for segmentation
  const segmentedClients = useMemo(() => {
    return clients.map(client => {
      const lastOrder = new Date(client.lastOrderDate);
      const daysSinceLastOrder = (new Date().getTime() - lastOrder.getTime()) / (1000 * 3600 * 24);

      let segment: ClientSegment = 'Potential Upsell';
      if (client.totalSpent > 10000000) segment = 'High Value';
      else if (daysSinceLastOrder > 30) segment = 'Lapsed';

      return { ...client, segment };
    });
  }, [clients]);

  const filteredClients = useMemo(() => {
    return segmentedClients.filter(c => {
      const matchesFilter = filter === 'All' || c.segment === filter;
      const matchesSearch = c.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           c.email.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesFilter && matchesSearch;
    });
  }, [segmentedClients, filter, searchQuery]);

  const generateInsights = async () => {
    setLoading(true);
    try {
      const res = await getSalesOutreachSuggestions(segmentedClients);
      setRecommendations(res);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const getSegmentStyles = (segment: ClientSegment) => {
    switch (segment) {
      case 'High Value': return 'bg-amber-50 text-amber-700 border-amber-100';
      case 'Lapsed': return 'bg-rose-50 text-rose-700 border-rose-100';
      case 'Potential Upsell': return 'bg-indigo-50 text-indigo-700 border-indigo-100';
    }
  };

  const getSegmentIcon = (segment: ClientSegment) => {
    switch (segment) {
      case 'High Value': return <TrendingUp size={12} />;
      case 'Lapsed': return <AlertCircle size={12} />;
      case 'Potential Upsell': return <UserCheck size={12} />;
    }
  };

  return (
    <div className="space-y-8 pb-10">
      {/* AI Header Section */}
      <div className="bg-slate-900 rounded-[2.5rem] p-8 md:p-10 text-white relative overflow-hidden shadow-2xl border border-white/5">
        <div className="relative z-10">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-3 bg-amber-500 rounded-2xl shadow-lg shadow-amber-500/20">
              <BrainCircuit size={28} />
            </div>
            <div>
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-amber-500 block mb-1">Sales Catalyst AI</span>
              <h2 className="text-3xl font-black">Proactive Outreach</h2>
            </div>
          </div>
          <p className="text-slate-400 max-w-xl mb-8 leading-relaxed font-medium">
            AI kami menganalisis kebiasaan pesan pelanggan katering Anda. Temukan siapa yang perlu Anda hubungi hari ini untuk meningkatkan omzet secara signifikan.
          </p>
          <button 
            onClick={generateInsights}
            disabled={loading}
            className="bg-white text-slate-900 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-amber-500 hover:text-white transition-all flex items-center gap-3 shadow-xl disabled:opacity-70 group"
          >
            {loading ? <Loader2 className="animate-spin" size={18} /> : <Sparkles size={18} />}
            Analisis Strategi Penjualan
          </button>
        </div>
        <div className="absolute top-0 right-0 w-96 h-96 bg-amber-500/10 rounded-full -mr-32 -mt-32 blur-[100px]"></div>
      </div>

      {/* AI Recommendations Cards */}
      {recommendations.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 animate-in slide-in-from-bottom-6 duration-700">
          {recommendations.map((rec, i) => (
            <div key={i} className="bg-white rounded-[2rem] border border-amber-100 p-6 flex flex-col justify-between shadow-xl shadow-amber-500/5 hover:scale-[1.02] transition-all relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity">
                <Star size={60} fill="currentColor" className="text-amber-500" />
              </div>
              <div>
                <div className="flex items-center justify-between mb-6">
                  <div className="px-3 py-1 bg-amber-50 text-amber-600 rounded-full text-[9px] font-black uppercase tracking-widest border border-amber-100">
                    AI Pick
                  </div>
                  <TrendingUp size={18} className="text-amber-500" />
                </div>
                <h3 className="font-black text-slate-900 text-xl mb-1">{rec.clientName}</h3>
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-wider mb-4 flex items-center gap-1.5">
                   <Calendar size={12} /> {rec.reason}
                </p>
                <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 mb-6 italic text-sm text-slate-700 leading-relaxed relative">
                  <span className="absolute -top-3 left-4 bg-white px-2 text-[10px] font-black text-amber-600 uppercase">Suggested Pitch</span>
                  "{rec.pitch}"
                </div>
              </div>
              <button className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.15em] flex items-center justify-center gap-2 hover:bg-amber-600 transition-all shadow-lg group">
                <Send size={14} className="group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
                Kirim via WhatsApp
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Client Database Section */}
      <div className="bg-white rounded-[2.5rem] p-8 md:p-10 border border-slate-100 shadow-sm relative overflow-hidden">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
          <div>
            <h3 className="text-2xl font-black text-slate-900 flex items-center gap-3">
              <UserCircle size={28} className="text-slate-300" />
              Database Pelanggan
            </h3>
            <p className="text-sm text-slate-400 font-medium mt-1">Kelola dan pantau loyalitas setiap pelanggan Anda.</p>
          </div>

          <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
            <div className="relative group">
              <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-amber-500 transition-colors" />
              <input 
                type="text" 
                placeholder="Cari nama atau email..." 
                className="pl-12 pr-6 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-sm font-semibold outline-none focus:ring-2 focus:ring-amber-500/20 focus:bg-white transition-all w-full sm:w-64"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>

            <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100">
              {(['All', 'High Value', 'Lapsed', 'Potential'] as const).map(s => (
                <button
                  key={s}
                  onClick={() => setFilter(s === 'Potential' ? 'Potential Upsell' : s as any)}
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                    (filter === 'All' && s === 'All') || (filter === s) || (filter === 'Potential Upsell' && s === 'Potential')
                      ? 'bg-white text-amber-600 shadow-sm' 
                      : 'text-slate-400 hover:text-slate-600'
                  }`}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredClients.map(client => (
            <div key={client.id} className="p-6 border border-slate-100 rounded-[2rem] bg-white hover:border-amber-200 hover:shadow-2xl hover:shadow-slate-100 transition-all group">
              <div className="flex justify-between items-start mb-6">
                <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center font-black text-slate-300 border border-slate-100 group-hover:bg-amber-50 group-hover:text-amber-500 group-hover:border-amber-100 transition-all">
                  {client.name.charAt(0)}
                </div>
                <div className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-[9px] font-black border uppercase tracking-widest ${getSegmentStyles(client.segment!)}`}>
                  {getSegmentIcon(client.segment!)}
                  {client.segment}
                </div>
              </div>

              <div className="mb-6">
                <h4 className="font-black text-slate-800 text-lg group-hover:text-amber-600 transition-colors">{client.name}</h4>
                <div className="flex items-center gap-2 text-slate-400 mt-1">
                  <Mail size={12} />
                  <span className="text-xs font-medium truncate">{client.email}</span>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex justify-between items-center p-3 bg-slate-50 rounded-xl group-hover:bg-amber-50/30 transition-colors">
                  <div>
                    <p className="text-[9px] text-slate-400 uppercase font-black tracking-widest leading-none mb-1">Total Omzet</p>
                    <p className="text-sm font-black text-slate-800">Rp {(client.totalSpent/1000000).toFixed(1)} JT</p>
                  </div>
                  <div className="text-right">
                    <p className="text-[9px] text-slate-400 uppercase font-black tracking-widest leading-none mb-1">Order Terakhir</p>
                    <p className="text-xs font-bold text-slate-600">{client.lastOrderDate}</p>
                  </div>
                </div>

                <button className="w-full flex items-center justify-between px-4 py-3 bg-white border border-slate-100 rounded-xl text-[10px] font-black uppercase tracking-widest text-slate-400 group-hover:text-amber-600 group-hover:border-amber-100 transition-all">
                  Lihat Detail History
                  <ChevronRight size={14} />
                </button>
              </div>
            </div>
          ))}
        </div>

        {filteredClients.length === 0 && (
          <div className="py-20 text-center bg-slate-50 rounded-[2rem] border border-dashed border-slate-200">
            <UserCircle size={48} className="mx-auto text-slate-200 mb-4" />
            <p className="text-slate-400 font-bold italic">Tidak ada pelanggan yang ditemukan...</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default SmartOutreach;

import React, { useState, useRef } from 'react';
import { Sparkles, Camera, Upload, CheckCircle2, AlertCircle, Loader2, Package, Utensils } from 'lucide-react';
import { diagnosePlantImage } from '../services/geminiService'; // Using same underlying service for catering diagnosis
import { AnalysisResult } from '../types';

const SmartAdvisor: React.FC = () => {
  const [analyzing, setAnalyzing] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64String = reader.result as string;
        setPreview(base64String);
        setAnalyzing(true);
        try {
          // Repurposed diagnose tool to look for ingredient health/freshness
          const res = await diagnosePlantImage(base64String);
          setResult(res);
        } catch (error) {
          console.error("AI Analysis failed", error);
        } finally {
          setAnalyzing(false);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-slate-900 rounded-[2.5rem] p-8 md:p-12 text-white relative overflow-hidden shadow-2xl">
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-10">
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-6">
              <div className="p-2 bg-amber-500 rounded-xl">
                <Utensils size={20} className="text-white" />
              </div>
              <span className="uppercase tracking-[0.3em] text-[10px] font-black text-amber-500">Kitchen AI Advisor</span>
            </div>
            <h2 className="text-4xl font-black mb-6 leading-tight">Optimasi Bahan Baku & Stok (MRP)</h2>
            <p className="text-slate-400 text-lg mb-8 leading-relaxed font-medium">
              Ambil foto bahan baku atau gudang Anda. AI kami akan mendeteksi kesegaran, memperkirakan sisa stok, atau memberikan saran penggunaan bahan sebelum kadaluarsa.
            </p>
            <div className="flex flex-wrap gap-4">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="bg-white text-slate-900 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-amber-500 hover:text-white transition-all flex items-center gap-3 shadow-xl"
              >
                <Camera size={20} />
                Foto Bahan Baku
              </button>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                className="hidden" 
                accept="image/*"
              />
            </div>
          </div>

          <div className="w-full md:w-80 aspect-square bg-white/5 rounded-[2.5rem] border-2 border-dashed border-white/10 flex flex-col items-center justify-center relative group transition-all hover:border-amber-500/50">
            {preview ? (
              <img src={preview} alt="Ingredient Preview" className="w-full h-full object-cover rounded-[2.3rem]" />
            ) : (
              <div className="text-center p-6">
                <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                  <Package size={40} className="text-slate-600" />
                </div>
                <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Drop Foto Bahan Di Sini</span>
              </div>
            )}
            {analyzing && (
              <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md rounded-[2.3rem] flex flex-col items-center justify-center">
                <div className="relative">
                   <Loader2 className="animate-spin text-amber-500 mb-4" size={48} />
                   <Sparkles className="absolute -top-2 -right-2 text-white animate-pulse" size={20} />
                </div>
                <span className="text-white text-[10px] font-black tracking-[0.3em] uppercase">AI MENGANALISIS...</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {result && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-8 duration-700">
          <div className="lg:col-span-1 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm h-fit">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Status Bahan Baku</h3>
            <div className="flex items-center gap-4 mb-8 bg-slate-50 p-4 rounded-2xl border border-slate-100">
              {result.status.toLowerCase().includes('bagus') || result.status.toLowerCase().includes('fresh') ? (
                <div className="p-3 bg-emerald-500 text-white rounded-xl shadow-lg shadow-emerald-500/20">
                  <CheckCircle2 size={24} />
                </div>
              ) : (
                <div className="p-3 bg-amber-500 text-white rounded-xl shadow-lg shadow-amber-500/20">
                  <AlertCircle size={24} />
                </div>
              )}
              <span className="text-xl font-black text-slate-800">{result.status}</span>
            </div>
            <div className="relative">
              <span className="absolute -top-3 left-4 bg-white px-2 text-[10px] font-black text-slate-400 uppercase">Diagnosis AI</span>
              <p className="text-slate-600 leading-relaxed italic border border-slate-100 p-5 rounded-2xl pt-6">
                "{result.diagnosis}"
              </p>
            </div>
          </div>

          <div className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-8">Rekomendasi Tindakan</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {result.recommendations.map((rec, i) => (
                <div key={i} className="flex gap-5 p-6 bg-slate-50 rounded-3xl border border-slate-100 hover:border-amber-200 hover:bg-amber-50/20 transition-all">
                  <div className="bg-white w-10 h-10 rounded-xl flex items-center justify-center font-black text-amber-500 shadow-sm border border-slate-100 flex-shrink-0">
                    {i + 1}
                  </div>
                  <p className="text-slate-700 text-sm font-semibold leading-relaxed">{rec}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

